import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:20.5px;line-height:1.28}.box h2{font-size:26px;margin-bottom:5px}.tbl{font-size:18.5px}.note,.warn{font-size:17.5px}.tbl th,.tbl td{padding:3px 6px}.iq ol{font-size:19.5px;line-height:1.28}.pill{font-size:16.5px}.grid{gap:12px}.handle{bottom:-12px}.box{padding:10px 12px}.tagline{font-size:19.5px;margin-bottom:9px}</style>
<div class="title">🔑 HxGN EAM Key Management <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Define physical keys and key rings, link them to locks and equipment, and track every issue and return to employees. (Infor EAM Key Management brief, 11.7 folder)</div>
<div class="grid">
<div class="box c1"><h2>1. Key vs Ring</h2><table class="tbl"><tr><th>Type</th><th>Use</th></tr><tr><td><b>Key</b> (default)</td><td>One key: Access Level, Parent Key, Supplier, Key Type, Key Decode</td></tr><tr><td><b>Ring</b></td><td>Groups keys; key-detail fields cleared + protected</td></tr></table><div class="note">Key/Ring, Organization and Type lock after save.</div></div>
<div class="box c2"><h2>2. Header fields</h2><ul><li>Status (protected): <b>In Stock</b> / <b>Issued</b></li><li><b>Lost</b> + <b>Out of Service</b> check boxes</li><li>Cabinet + Position = where it hangs</li><li>Supplier Key Number, Manufacturer</li></ul></div>
<div class="box c3"><h2>3. Issue a key</h2><ul><li>Enter <b>Employee</b>: Job Title + Department fill in</li><li>Save = <b>Issue</b> transaction</li><li>Issue Date = today, Status = <b>Issued (I)</b></li><li>Issue Expiration Date unlocks</li></ul></div>
<div class="box c4"><h2>4. Return / reassign</h2><ul><li>Clear Employee + save = <b>Return</b>, Status <b>In Stock (S)</b></li><li>Change Employee = Return (old) + Issue (new)</li><li>Holder Notes + dates are cleared</li></ul><div class="warn">Expiration Date must be ≥ Issue Date.</div></div>
<div class="box c5"><h2>5. Locks tab</h2><ul><li>Lock + Description, Location, <b>Cylinder Number</b></li><li>Link Equipment: Dept + Workspace default from it</li><li>Lock may or may not belong to equipment</li></ul><div class="note">Not editable when Type = Ring.</div></div>
<div class="box c6"><h2>6. Ring Keys tab</h2><ul><li>Add keys to a Ring record</li><li>Key gets <b>Parent Ring</b> + Holder Notes</li><li>Locked when Status = Issued</li><li>Ring holder change copies to all its keys</li></ul></div>
<div class="box c7"><h2>7. Copy Key popup</h2><ul><li>New Key + Description; copy Locks, Comments, Documents</li><li>Copy resets to In Stock, no holder, no Parent Ring</li></ul><div class="warn">Copy Key is blocked for Rings.</div></div>
<div class="box c8"><h2>8. Where keys show up</h2><ul><li><b>Transactions</b> tab: read-only issue / return log</li><li><b>Keys</b> tab on Assets, Positions, Systems, Facilities, Rooms, Vehicles...</li><li><b>Keys</b> tab on Employees</li><li>Reports: <b>Key List-Detail</b>, <b>Ring List-Detail</b></li></ul></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">9a. Key lifecycle</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">Define key + lock</span><span class="arr">→</span><span class="pill">Add to Ring</span><span class="arr">→</span><span class="pill">Issue to Employee</span><span class="arr">→</span><span class="pill">Return / reassign</span></div></div>
<div class="box iq"><h2>9b. Consultant tips</h2><ol><li>Issue the Ring, not each key</li><li>Always set an Issue Expiration Date for contractors</li><li>Use Cabinet + Position for the key cabinet</li><li>Audit with the Employees Keys tab at exit</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">9c. Key points</h2><ul><li>Save = transaction</li><li>Ring drives its keys</li><li>Lost flag ≠ return</li></ul></div>
</div></div>'''
build("/workspace/social/posts/2026-10-24-linkedin-eam-key-management",B,1350,"Rahul Kumar")
